// ── Your settings ────────────────────────────────────────────────────────────
const WORKSPACE_ID = 0;        // PaperOffice workspace with invoices, purchase orders and delivery notes
const HITL_AGENT_UUID = '';    // PaperOffice app → Workflow AI → HITL agents → your agent → UUID
// ─────────────────────────────────────────────────────────────────────────────
// Checked before any API call: a rejected request still costs the minimum price.
if (!(Number(WORKSPACE_ID) > 0)) throw new Error('Enter your PaperOffice workspace ID in the "Settings" node.');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(HITL_AGENT_UUID)) {
  throw new Error('Enter the UUID of your HITL agent in the "Settings" node.');
}
const bin = $input.item.binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('No PDF was uploaded.');
const name = String(bin[key].fileName || 'invoice.pdf');
if (!/\.pdf$/i.test(name) && String(bin[key].mimeType || '') !== 'application/pdf') throw new Error('Please upload a PDF.');
const deep = /^yes/i.test(String($json['Deep check with AI-DMS Ultra'] || ''));
return { json: { workspace_id: Number(WORKSPACE_ID), agent_uuid: HITL_AGENT_UUID, deep_check: deep, file_name: name }, binary: { invoice: bin[key] } };

// Reads results[0].pofid of the upload. Without it nothing else may run.
const body = ($json.body !== undefined ? $json.body : $json) || {};
const code = Number($json.statusCode || 0);
if (code === 401 || code === 403) throw new Error('PaperOffice AI rejected the API key (HTTP ' + code + '). Create a User token (po_ut_…) under Account → API.');
const r = Array.isArray(body.results) ? body.results[0] : null;
if (!r || !r.pofid) throw new Error('Upload failed: ' + (body.message || body.code || ('HTTP ' + code)));
return { json: { ...$('Settings').item.json, pofid: r.pofid, documents_id: r.documents_id } };

// Invoice fields from result.pages_idp[].suggested_fields (object or array form). A job that is still
// running (HTTP 202) is NOT waited for here: the invoice then goes to review with "extraction unknown".
const s = $('Check upload').item.json;
const body = ($json.body !== undefined ? $json.body : $json) || {};
const payload = body.result || body.job_result || {};
const pages = Array.isArray(payload.pages_idp) ? payload.pages_idp : [];
function raw(key) {
  for (const p of pages) {
    const sf = p && p.suggested_fields;
    if (!sf) continue;
    const f = Array.isArray(sf) ? sf.find((x) => x && (x.key === key || x.category === key)) : sf[key];
    if (f === undefined || f === null) continue;
    const v = typeof f === 'object' ? f.value : f;
    if (v === 'VALUE_MISSING' || v === undefined || v === null || String(v).trim() === '') continue;
    return { value: v, raw: typeof f === 'object' && f.value_raw != null ? f.value_raw : v };
  }
  return null;
}
const text = (k) => { const f = raw(k); return f ? String(f.value).trim() : ''; };
const num = (k) => { const f = raw(k); if (!f) return null; const m = /-?\d+(?:\.\d+)?/.exec(String(f.raw).replace(',', '.')); return m ? Number(m[0]) : null; };
const lineItems = (() => { const f = raw('_line_items'); const v = f ? f.value : null; if (Array.isArray(v)) return v; if (v && Array.isArray(v.value)) return v.value; try { const j = JSON.parse(v); return Array.isArray(j) ? j : (j && Array.isArray(j.value) ? j.value : []); } catch (e) { return []; } })();
return { json: {
  ...s,
  extracted: pages.length > 0,
  supplier: text('_supplier_name'),
  supplier_vat_id: text('_supplier_vat_id'),
  invoice_number: text('_invoice_number'),
  invoice_date: text('_invoice_date'),
  due_date: text('_payment_due_date'),
  total_amount: num('_total_amount'),
  currency: text('_currency') || 'EUR',
  iban: text('_creditor_iban').replace(/\s+/g, '').toUpperCase(),
  order_number: text('__document__data__metadata__reference_number') || text('_document__data__metadata__reference_number'),
  line_items: lineItems.map((it) => ({ code: String(it.item_code || it.sku || it.article_number || '').trim(), quantity: Number(String(it.quantity ?? '').replace(',', '.')) || 0, total: Number(String(it.total_price ?? it.total_price_net ?? '').replace(',', '.')) || 0 })),
} };

// Earlier invoices of the supplier (up to 5) and documents that mention the order number (up to 6) whose OCR text is read next.
const inv = $('Read invoice').item.json;
const list = (node) => { const b = ($(node).item.json.body) || {}; return Array.isArray(b.documents) ? b.documents : []; };
const out = [];
const seen = new Set([inv.pofid]);
// Each document once. Other invoices with the same order number also match the order search, so it reads up to 6.
const add = (d, role) => { if (d.pofid && !seen.has(d.pofid)) { seen.add(d.pofid); out.push({ json: { pofid: d.pofid, role, file_name: d.file_name || '' } }); } };
list('Find earlier invoices').filter((d) => d.pofid && d.pofid !== inv.pofid).slice(0, 5).forEach((d) => add(d, 'history'));
list('Find order and delivery note').filter((d) => d.pofid && !seen.has(d.pofid)).slice(0, 6).forEach((d) => add(d, 'order'));
if (out.length === 0) out.push({ json: { pofid: inv.pofid, role: 'self', file_name: inv.file_name } });
return out;

// IBANs of earlier invoices (MOD 97 valid only) and the purchase order / delivery note among the order documents.
const inv = $('Read invoice').first().json;
const plan = $('Pick documents to read').all().map((i) => i.json);
// ocr-get answers with plain text or with JSON {data: "..."}; never search in a JSON string (escaped line breaks hide word boundaries)
const texts = $input.all().map((i) => { const b = (i.json.body !== undefined ? i.json.body : i.json) || {}; if (typeof b === 'string') { try { const j = JSON.parse(b); if (j && typeof j.data === 'string') return j.data; } catch (x) { /* plain text */ } return b; } return String(b.text || b.ocr_text || b.content || b.data || JSON.stringify(b)); });
function ibanOk(s) { const r = s.slice(4) + s.slice(0, 4); let m = 0; for (const ch of r) { const v = /\d/.test(ch) ? ch : String(ch.charCodeAt(0) - 55); for (const c of v) m = (m * 10 + Number(c)) % 97; } return m === 1; }
function ibans(t) { const out = new Set(); const re = /\b([A-Z]{2}\d{2}(?:[ ]?[A-Z0-9]{4}){2,7}(?:[ ]?[A-Z0-9]{1,3})?)\b/g; let m; while ((m = re.exec(String(t).toUpperCase()))) { const s = m[1].replace(/\s+/g, ''); if (s.length >= 15 && s.length <= 34 && ibanOk(s)) out.add(s); } return [...out]; }
const history_ibans = new Set(); let history_docs = 0; let po = null; let dn = null; let po_total = null; const billed = [];
// Largest money amount in a text = the gross total (OCR may put the label before or after the number). "6.012,48" and "6,012.48" both work.
const max_amount = (t) => { let best = null; const re = /(?:€|EUR|\$|£|CHF)?\s?(\d{1,3}(?:[.,\s]\d{3})*(?:[.,]\d{2})|\d+[.,]\d{2})(?!\d)/g; let m;
  while ((m = re.exec(String(t)))) { let v = m[1].replace(/\s/g, ''); const dec = v.slice(-3, -2); v = v.slice(0, -3).replace(/[.,]/g, '') + '.' + v.slice(-2); if (dec !== '.' && dec !== ',') continue; const n = Number(v); if (Number.isFinite(n) && (best === null || n > best)) best = n; }
  return best; };
// Compare numbers without case, spaces, dashes, dots or slashes (OCR writes "NS PO 2026 0412" as well).
// Short numbers (under 5 characters or without a digit) must appear as a whole word instead, so "4711" does not match a phone number.
const norm = (v) => String(v || '').toUpperCase().replace(/[\s\-_.\/]+/g, '');
const order_key = norm(inv.order_number);
const invoice_key = norm(inv.invoice_number);
const esc = (v) => String(v).replace(/[.*+?^(){}|[\]\\$]/g, '\\$&');
const names_order = (t) => order_key.length >= 5 && /\d/.test(order_key)
  ? norm(t).includes(order_key)
  : new RegExp('(^|[^A-Za-z0-9])' + esc(String(inv.order_number).trim()) + '($|[^A-Za-z0-9])', 'i').test(t);
plan.forEach((p, i) => {
  const t = texts[i] || '';
  // Belege mit derselben Rechnungsnummer (Dubletten) zählen nicht als Vergleichsbasis für die IBAN
  if (p.role === 'history' && !(inv.invoice_number && t.includes(inv.invoice_number))) { history_docs++; ibans(t).forEach((x) => history_ibans.add(x)); }
  // Order and delivery note: the document type is the title word that comes FIRST in the text (footers such as
  // "quote the order number on delivery note and invoice" come later). An invoice never counts as an order, even when it
  // names the order number ("Ihre Bestellung NS-PO-…"). Order and delivery note must name the order number of this invoice.
  const first = (re) => { const m = re.exec(t.slice(0, 1500)); return m ? m.index : Infinity; };
  // Invoice-like: invoices and credit notes. Within the first 300 characters the invoice title wins, so a supplier named
  // "Ordine Srl" above "FATTURA" is still an invoice.
  let at_invoice = Math.min(first(/\b(invoice|rechnung|factura|facture|fattura|faktura|faktúra|fatura|factuur|gutschrift|credit note|avoir|nota di credito|nota de crédito|korekta|dobropis)\b(?!\s*(address|adresse|to)\b)/i), invoice_key !== '' && norm(t.slice(0, 600)).includes(invoice_key) ? -1 : Infinity);
  if (at_invoice < 300) at_invoice = -1;
  const at_dn = first(/delivery note|lieferschein|bon de livraison|albar[aá]n|bolla di consegna|dowód dostawy|dodací list/i);
  const at_po = first(/purchase order|bestellung|commande|pedido|ordine|zamówienie|objednávka/i);
  if (order_key === '' || !names_order(t)) return;
  if (at_invoice < Math.min(at_dn, at_po)) {
    // v5: another invoice (not a credit note, not a copy of this invoice number) that bills the same order
    const credit = /\b(gutschrift|credit note|nota di credito|nota de crédito)\b|\b(AVOIR|KOREKTA|DOBROPIS)\b/i.test(t.slice(0, 600));
    const num = (t.match(/(?:invoice\s*(?:number|no\.?|#)|rechnungs?\s*(?:nummer|nr\.?)|factura\s*(?:n[º°o]\.?|número)|facture\s*n[°o]|fattura\s*n\.?)\s*[:#]?\s*([A-Z0-9][A-Z0-9\-\/\.]{2,30})/i) || [])[1] || '';
    if (!credit && !(invoice_key !== '' && (norm(num) === invoice_key || norm(t.slice(0, 600)).includes(invoice_key)))) {
      billed.push({ pofid: p.pofid, file_name: p.file_name || '', invoice_number: num, total: max_amount(t) });
    }
    return;
  }
  if (!dn && at_dn < at_po) dn = p.pofid;
  else if (!po && at_po < at_dn) { po = p.pofid; po_total = max_amount(t); }
});
// One entry per invoice number (scans or copies of the same earlier invoice count once)
const billed_by = [];
for (const b of billed) { const k = norm(b.invoice_number) || b.pofid; if (!billed_by.some((x) => (norm(x.invoice_number) || x.pofid) === k)) billed_by.push(b); }
return [{ json: { ...inv, history_docs, history_ibans: [...history_ibans], po_pofid: po, dn_pofid: dn, po_total, billed_by } }];

// One result per check: ok | finding | unknown. unknown counts as a finding (fail-closed). Never "approve" here.
const e = $('Collect evidence').first().json;
const body = (n) => { try { const j = $(n).first().json; return (j.body !== undefined ? j.body : j) || {}; } catch (x) { return null; } };
const fields = (b) => { const p = (b && (b.result || b.job_result)) || {}; const pages = Array.isArray(p.pages_idp) ? p.pages_idp : []; return pages; };
// Quantities come as "10", "10 pcs" or "2,5 kg": take the first number
const qty = (v) => { const m = String(v ?? '').match(/-?\d+(?:[.,]\d+)?/); return m ? Number(m[0].replace(',', '.')) : 0; };
const idpItems = (b) => { for (const pg of fields(b)) { const sf = pg.suggested_fields || {}; const f = Array.isArray(sf) ? sf.find((x) => x && (x.key === '_line_items' || x.category === '_line_items')) : sf._line_items; let v = f && typeof f === 'object' ? f.value : f; if (typeof v === 'string') { try { v = JSON.parse(v); } catch (x) { v = null; } } if (v && Array.isArray(v.value)) v = v.value; if (Array.isArray(v)) return v.map((it) => ({ code: String(it.item_code || it.sku || it.article_number || '').trim().toUpperCase(), quantity: qty(it.quantity ?? it.qty_shipped ?? it.qty_delivered ?? it.quantity_delivered ?? it.qty) })); } return null; };
const findings = [];
const checks = {};
// 1. Extraction
checks.extraction = e.extracted ? 'ok' : 'unknown';
if (!e.extracted) findings.push('Invoice data could not be read completely (job still running or failed).');
// 2. IBAN (Begriffe wie c0: iban_check.status, check_id iban_changed)
let iban_status = 'unknown';
if (e.iban && e.history_ibans.length > 0) iban_status = e.history_ibans.includes(e.iban) ? 'match' : 'changed';
checks.iban = iban_status === 'match' ? 'ok' : (iban_status === 'changed' ? 'finding' : 'unknown');
if (iban_status === 'changed') findings.push('IBAN ' + e.iban + ' differs from earlier invoices of ' + (e.supplier || 'this supplier') + ' (' + e.history_ibans.join(', ') + '). Confirm the bank details with a known contact before paying.');
if (iban_status === 'unknown') findings.push(e.iban ? 'No earlier invoice of this supplier found to compare the IBAN (new supplier?).' : 'No IBAN found on the invoice.');
// 3. Duplicate
const dup = body('Duplicate check') || {};
const same = ((body('Find same invoice number') || {}).documents || []).filter((d) => d.pofid && d.pofid !== e.pofid);
const dupHit = Boolean(dup.is_duplicate || (Array.isArray(dup.duplicates) && dup.duplicates.length) || same.length);
checks.duplicate = dupHit ? 'finding' : (e.invoice_number ? 'ok' : 'unknown');
if (dupHit) findings.push('Possible duplicate: invoice number ' + (e.invoice_number || '?') + ' already exists in the workspace.');
// 4. Order and delivery note
let match = 'no_po_reference';
let poItems = null;
let dnItems = null;
if (e.order_number) {
  poItems = e.po_pofid ? idpItems(body('Extract order')) : null;
  dnItems = e.dn_pofid ? idpItems(body('Extract delivery note')) : null;
  if (!e.po_pofid) match = 'po_not_found';
  else if (!e.dn_pofid) match = 'delivery_not_found';
  else if (!poItems || !dnItems) match = 'unknown';
  else {
    const q = (list, code) => list.filter((x) => x.code === code).reduce((s, x) => s + x.quantity, 0);
    const bad = e.line_items.filter((it) => it.code && (it.quantity > q(dnItems, it.code.toUpperCase()) || it.quantity > q(poItems, it.code.toUpperCase())));
    match = bad.length ? 'quantity_mismatch' : 'ok';
    if (bad.length) findings.push('Billed more than delivered or ordered: ' + bad.map((b) => b.code + ' × ' + b.quantity).join(', ') + '.');
  }
}
checks.order = match === 'ok' ? 'ok' : 'finding';
// 5. Order already billed by other invoice(s) (v5)
const billed_by = Array.isArray(e.billed_by) ? e.billed_by : [];
let over_billed = false;
if (billed_by.length) {
  checks.billed = 'finding';
  const sum = billed_by.reduce((s, b) => s + (Number(b.total) || 0), 0) + (Number(e.total_amount) || 0);
  findings.push('Order ' + e.order_number + ' is already billed by ' + billed_by.map((b) => (b.invoice_number || b.file_name || '?') + (b.total ? ' (' + b.total.toFixed(2) + ')' : '')).join(', ') + '. Check the remaining quantity before paying.');
  if (e.po_total && sum > Number(e.po_total) + 0.01) {
    over_billed = true;
    findings.push('All invoices for order ' + e.order_number + ' together (' + sum.toFixed(2) + ') exceed the order total (' + Number(e.po_total).toFixed(2) + ').');
  }
} else checks.billed = 'ok';
if (match === 'po_not_found') findings.push('Order ' + e.order_number + ' was not found in the workspace.');
if (match === 'delivery_not_found') findings.push('No delivery note found for order ' + e.order_number + '.');
if (match === 'no_po_reference') findings.push('The invoice has no order number.');
if (match === 'unknown') findings.push('Order or delivery note could not be read.');
const risk = findings.length === 0 ? 'low' : (checks.iban === 'finding' || checks.duplicate === 'finding' || over_billed ? 'high' : 'medium');
// The values this check was based on, so a reviewer or another assistant reading the note sees the same evidence
const groups4 = (v) => String(v || '').replace(/\s+/g, '').replace(/(.{4})(?=.)/g, '$1 ');
const plan_docs = $('Pick documents to read').all().map((i) => i.json);
const doc_name = (pofid) => ((plan_docs.find((p) => p.pofid === pofid) || {}).file_name || pofid || '?');
const sum_qty = (list, code) => (list ? list.filter((x) => x.code === code).reduce((s, x) => s + x.quantity, 0) : null);
const history_names = [...new Set(plan_docs.filter((p) => p.role === 'history' && p.pofid !== e.po_pofid && p.pofid !== e.dn_pofid).map((p) => p.file_name).filter(Boolean))];
const lines = [
  'Fraud check (n8n) — ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC',
  'Supplier: ' + (e.supplier || '?') + ' · Invoice: ' + (e.invoice_number || '?') + ' · Total: ' + (e.total_amount ?? '?') + ' ' + e.currency,
  'IBAN check: ' + iban_status + ' · Duplicate: ' + checks.duplicate + ' · Order/delivery: ' + match,
  'Risk: ' + risk + (findings.length ? '' : ' — no findings, approval by a reviewer is still required'),
  ...findings.map((f) => '• ' + f),
  '',
  'Read from the invoice:',
  '• Invoice ' + (e.invoice_number || '?') + (e.invoice_date ? ' of ' + e.invoice_date : '') + (e.due_date ? ' · due ' + e.due_date : '') + ' · total ' + (e.total_amount ?? '?') + ' ' + (e.currency || '') + ' · order ' + (e.order_number || 'none'),
  '• IBAN on the invoice: ' + (e.iban ? groups4(e.iban) : 'none found'),
  '• Known IBANs of this supplier: ' + (e.history_ibans.length ? e.history_ibans.map(groups4).join(', ') : 'none found'),
  ...(e.line_items.length
    ? ['• Items (invoiced / delivered / ordered):', ...e.line_items.map((it) => '  ' + (it.code || '?') + ': ' + it.quantity + ' / ' + (sum_qty(dnItems, String(it.code || '').toUpperCase()) ?? '–') + ' / ' + (sum_qty(poItems, String(it.code || '').toUpperCase()) ?? '–'))]
    : ['• Items: none read']),
  '• Order total: ' + (e.po_total ? Number(e.po_total).toFixed(2) : 'not read') + ' · already billed by: ' + (billed_by.length ? billed_by.map((b) => (b.invoice_number || b.file_name) + (b.total ? ' ' + b.total.toFixed(2) : '')).join(', ') : 'no other invoice'),
  'Compared with: order ' + (e.po_pofid ? doc_name(e.po_pofid) : 'not found') + ' · delivery note ' + (e.dn_pofid ? doc_name(e.dn_pofid) : 'not found') + ' · earlier invoices ' + (history_names.length ? history_names.join(', ') : 'none'),
  '',
  'No payment is released by this workflow. The reviewer decides.',
];
return [{ json: { pofid: e.pofid, agent_uuid: e.agent_uuid, deep_check: e.deep_check, risk, findings, iban_check: { status: iban_status, check_id: 'iban_changed' }, duplicate: checks.duplicate, order_match: match, report: lines.join('\n') } }];

// Compares X-PaperOffice-Signature with the HMAC computed by "Compute signature" over the RAW body (constant-time).
// Works without the "crypto" module, so it runs on n8n Cloud and self-hosted alike. Anything missing → invalid → 401.
const hook = $('Review decision').first().json;
const headers = hook.headers || {};
const sig = String(headers['x-paperoffice-signature'] || '');
const raw = String($('Read raw body').first().json.raw_body || '');
const expected = 'sha256=' + String($input.first().json.expected_signature || '');
let valid = raw.length > 0 && expected.length === 71 && sig.length === expected.length;
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= (sig.charCodeAt(i) || 0) ^ expected.charCodeAt(i);
valid = valid && diff === 0;
let payload = {};
try { payload = JSON.parse(raw); } catch (e) { payload = {}; }
return [{ json: { valid, event: String(headers['x-paperoffice-event'] || payload.event_type || ''), event_id: String(headers['x-paperoffice-event-id'] || payload.event_id || ''), data: payload.data || {} } }];

// Only a reviewers' approval leads to "ready for payment". Escalation, rejection or anything else blocks.
const d = $json.data || {};
const approved = $json.event === 'hitl.review.consensus_completed' && String(d.final_decision || '') === 'approve';
return [{ json: { pofid: d.pofid || '', approved, decision: d.final_decision || $json.event, task_uuid: d.task_uuid || '' } }];
